mapper.select:
SELECT je.JOB_INSTANCE_ID AS job_instance_id, je.JOB_EXECUTION_ID AS job_execution_id, je.STATUS AS status, je.START_TIME AS start_time, je.END_TIME AS end_time, je.EXIT_MESSAGE AS job_exit_message, jp.PARAMETER_VALUE AS discogs_master_id, se.STEP_EXECUTION_ID AS step_execution_id, se.READ_COUNT AS read_count, se.WRITE_COUNT AS write_count, se.FILTER_COUNT AS filter_count, se.READ_SKIP_COUNT AS read_skip_count, se.WRITE_SKIP_COUNT AS write_skip_count, se.PROCESS_SKIP_COUNT AS process_skip_count, se.EXIT_MESSAGE AS step_exit_message FROM BATCH_JOB_EXECUTION je JOIN ( SELECT JOB_INSTANCE_ID, MAX(JOB_EXECUTION_ID) AS JOB_EXECUTION_ID FROM BATCH_JOB_EXECUTION WHERE JOB_INSTANCE_ID IN
#{jobInstanceId}
GROUP BY JOB_INSTANCE_ID ) latest ON latest.JOB_INSTANCE_ID = je.JOB_INSTANCE_ID AND latest.JOB_EXECUTION_ID = je.JOB_EXECUTION_ID LEFT JOIN BATCH_JOB_EXECUTION_PARAMS jp ON jp.JOB_EXECUTION_ID = je.JOB_EXECUTION_ID AND jp.PARAMETER_NAME = #{masterIdParameterName} LEFT JOIN BATCH_STEP_EXECUTION se ON se.JOB_EXECUTION_ID = je.JOB_EXECUTION_ID ORDER BY je.JOB_EXECUTION_ID, se.STEP_EXECUTION_ID
